test("parser odrzuca duplikaty, ułamki i nieznany status",()=>{for(const raw of [[{status:"OPEN",total:1},{status:"OPEN",total:2}],[{status:"OPEN",total:.5}],[{status:"OTHER",total:1}],[{status:"OPEN",total:Number.MAX_SAFE_INTEGER},{status:"CLOSED",total:1}]])expect(()=>parseCounts(raw)).toThrow();expect(commentText("  Nowy komentarz  ")).toBe("Nowy komentarz");});
