test("brak sesji, roli lub dostępu nigdy nie wykonuje zapisu",async()=>{const save=vi.fn(async()=>({id:"c1"}));for(const session of [null,{...user,canComment:false}]){const action=createCommentService({session:async()=>session,findTicket:async id=>({id,tenantId:"t1"}),save});await expect(action(42,"Tekst")).rejects.toThrow();}const action=createCommentService({session:async()=>user,findTicket:async id=>({id,tenantId:"obcy"}),save});await expect(action(42,"Tekst")).rejects.toThrow("Brak dostępu");expect(save).not.toHaveBeenCalled();});
test("niepoprawne wejście i obca tożsamość nie wykonują zapisu",async()=>{const save=vi.fn(async()=>({id:"c1"})),findTicket=vi.fn(async()=>({id:7,tenantId:"t1"})),action=createCommentService({session:async()=>user,findTicket,save});await expect(action(0,"Tekst")).rejects.toThrow();await expect(action(42,"a")).rejects.toThrow();expect(findTicket).not.toHaveBeenCalled();await expect(action(42,"Tekst")).rejects.toThrow("Brak dostępu");expect(save).not.toHaveBeenCalled();});
test("wyspa kliencka filtruje gotowy agregat i renderuje slot",()=>{render(<StatusFilter report={parseCounts([{status:"OPEN",total:3},{status:"CLOSED",total:2}])}><p>Treść slotu</p></StatusFilter>);expect(screen.getAllByRole("row")).toHaveLength(4);fireEvent.change(screen.getByRole("combobox"),{target:{value:"CLOSED"}});expect(screen.getAllByRole("row")).toHaveLength(2);expect(within(screen.getAllByRole("row")[1]).getAllByRole("cell").map(cell=>cell.textContent)).toEqual(["CLOSED","2"]);expect(screen.getByText("Treść slotu")).toBeVisible();});

